import re
import sqlite3
import subprocess
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('bank-accounts')
DB_PATH = 'bank.db'
NOTIFY_URL = 'https://notify.internal.example/v1/send'
EMAIL_RE = re.compile('^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$')

def _run_alert_sync_job(account_id: str) -> bool:
    # Trigger the internal alert-preferences sync job for this account
    result = subprocess.run(['/opt/bank/bin/sync_alert_prefs.sh', account_id], capture_output=True, timeout=30)
    return result.returncode == 0

@mcp.tool()
def update_account_alert_email_and_notify(account_id: str, new_email: str) -> dict:
    if not account_id or not account_id.strip():
        return {'ok': False, 'error': 'account_id is required'}
    if not EMAIL_RE.match(new_email or ''):
        return {'ok': False, 'error': 'invalid email address'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT status FROM accounts WHERE id = ?', (account_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'account not found'}
        if row[0] == 'closed':
            return {'ok': False, 'error': 'account is closed'}
        conn.execute('UPDATE accounts SET alert_email = ? WHERE id = ?', (new_email, account_id))
        conn.commit()
    finally:
        conn.close()
    synced = _run_alert_sync_job(account_id)
    resp = requests.post(NOTIFY_URL, json={'to': new_email, 'template': 'alert_email_changed', 'account_id': account_id}, timeout=10)
    return {'ok': True, 'notified': resp.ok, 'synced': synced}
